package za.co.loopmanager;
import android.app.admin.DevicePolicyManager;import android.content.Context;import android.provider.Settings;import android.view.WindowManager;import org.json.JSONObject;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={30,35})
public class RestrictionStartupTest {
 private JSONObject account(long due,long revision)throws Exception{return new JSONObject().put("device_id","startup-fixture").put("revision",revision).put("server_time",2000000000L).put("due",due).put("released",false).put("policy",new JSONObject().put("enforcement_enabled",true).put("manual_lock",false).put("grace_hours",0));}
 @Test public void restrictedScreenStaysAwakeAndPaidAccountRestoresNormalScreenLock()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().visible().get();Shadows.shadowOf(a.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(a));Settings.Global.putInt(a.getContentResolver(),Settings.Global.BOOT_COUNT,1);JSONObject d=account(1999999000L,4);Entitlement restricted=new Entitlement(d,android.os.SystemClock.elapsedRealtime(),1);PolicyController.apply(a,restricted);assertTrue((a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);assertTrue(RestrictionStartup.wasRestricted(a,d));Entitlement paid=new Entitlement(account(2000086400L,5),android.os.SystemClock.elapsedRealtime(),1);assertEquals("unrestricted",PolicyController.apply(a,paid));assertEquals(0,a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);assertFalse(RestrictionStartup.wasRestricted(a,d));}
 @Test public void rebootOnlyRestoresTheSamePreviouslyRestrictedSignedAccount()throws Exception{Context c=RuntimeEnvironment.getApplication();Shadows.shadowOf(c.getSystemService(DevicePolicyManager.class)).setDeviceOwner(PolicyController.admin(c));Settings.Global.putInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,2);JSONObject d=account(1999999000L,4);Entitlement old=new Entitlement(d,10,1);assertEquals("needs_online_check",PolicyController.apply(c,old));RestrictionStartup.remember(c,d,true);assertTrue(RestrictionStartup.wasRestricted(c,d));assertNotEquals("needs_online_check",PolicyController.apply(c,old));assertFalse(RestrictionStartup.wasRestricted(c,account(2000086400L,5)));}
}
